const o=[{id:"F01",title:"Monsell · 2003 · Passare da un compito all’altro",url:"https://psychfiles.net/experimental/Monsell_2003.pdf",type:"research",finding:"Negli studi di laboratorio su compiti semplici, dopo un cambio le risposte erano più lente e spesso meno accurate. Prepararsi riduceva questo costo senza eliminarlo in modo affidabile.",limitation:"Rassegna narrativa, senza una stima complessiva delle perdite sul lavoro. Non indica tempi universali di ripresa, percentuali di produttività o verifiche dei suggerimenti di preparazione di ODA."},{id:"F02",title:"Albulescu e colleghi · 2022 · Brevi pause",url:"https://doi.org/10.1371/journal.pone.0272460",type:"research",finding:"22 campioni, 2.335 partecipanti: energia d = 0,36 [0,16; 0,55], miglioramento della fatica 0,35 [0,19; 0,50], prestazione 0,16 [-0,04; 0,37].",limitation:"Campioni diversi per ciascun esito; dati limitati ed eterogenei. Non stabilisce durata o attività ideali, benefici affidabili sui compiti impegnativi o che ogni svago davanti a uno schermo impedisca di recuperare energia."},{id:"F03",title:"Harkin e colleghi · 2016 · Seguire i progressi verso un obiettivo",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 studi randomizzati, 19.951 partecipanti complessivi: osservare i progressi migliorava in media il raggiungimento degli obiettivi, d = 0,40 [0,32; 0,48].",limitation:"Obiettivi e metodi diversi. Le associazioni tra variabili non convalidano un diario specifico, non impongono condivisioni pubbliche e non dimostrano che questa precisa routine migliori i risultati."},{id:"F04",title:"Gollwitzer e Sheeran · 2006 · Intenzioni di attuazione",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"94 prove con 8.461 partecipanti: i piani specifici «se... allora...» favorivano in media il raggiungimento degli obiettivi, d = 0,65 [0,60; 0,70].",limitation:"Studi meno recenti ed eterogenei. Non garantisce l’effetto di una frase contro la voglia di controllare il telefono, né convalida un metodo completo di pianificazione per fasce orarie."},{id:"F06",title:"Kushlev, Proulx e Dunn · 2016 · Telefono con meno interruzioni",url:"https://interruptions.net/literature/Kushlev-CHI16.pdf",type:"research",finding:"221 studenti provarono due configurazioni per una settimana ciascuna. I confronti appaiati sui sintomi comprendevano 190 rispondenti. Avvisi disattivati e telefono fuori vista riducevano modestamente la disattenzione riferita: 2,27 contro 2,38; d = 0,44.",limitation:"Avvisi e visibilità/accessibilità cambiavano insieme. Autovalutazioni in uno studio non in cieco; non isola gli avvisi, non tratta l’ADHD e non mostra un miglioramento diretto significativo della produttività."},{id:"F07",title:"Mark, Gudith e Klocke · 2008 · Lavoro interrotto, velocità e stress",url:"https://ics.uci.edu/~gmark/chi08-mark.pdf",type:"research",finding:"48 partecipanti, in un lavoro simulato sulle email, impiegavano meno tempo netto con interruzioni ma riferivano più stress. Il tempo per gestire le interruzioni era sottratto.",limitation:"Campione piccolo, soprattutto studenti. Non dimostra meno tempo totale, qualità invariata garantita, effetti duraturi sullo stress o un tempo universale di ripresa."},{id:"F08",title:"Biwer e colleghi · 2023 · Pause di studio fisse o scelte liberamente",url:"https://doi.org/10.1111/bjep.12593",type:"research",finding:"110 studenti randomizzati, 87 analizzati in una sessione di due ore. Le sequenze fisse 24/6 o 12/3 mostravano esperienze favorevoli; nessuna differenza significativa nei compiti completati.",limitation:"Abbandoni ed esclusioni; lo studio più lungo previsto fu ridotto a una sessione. Non stabilisce intervalli ideali universali, benefici duraturi sull’apprendimento o validità dell’intero metodo Pomodoro."},{id:"F10",title:"Leroy e Glomb · 2018 · Interruzioni e piani per riprendere",url:"https://ideas.repec.org/a/inm/ororsc/v29y2018i3p380-397.html",type:"research",finding:"Quattro studi riportavano che pianificare la ripresa riduceva l’attenzione rimasta sul compito precedente e favoriva decisioni o il ricordo delle informazioni nel nuovo compito. Il primo studio sul campo era un’indagine.",limitation:"Disponibili solo abstract e sintesi universitaria. Scheda esatta, durata ed effetti complessivi non verificati. Nessun beneficio dimostrato sul compito originale una volta ripreso."},{id:"F11",title:"Lopez e colleghi · 2018 · Rassegna Cochrane sulla terapia cognitivo comportamentale per l’ADHD adulto",url:"https://www.cochrane.org/evidence/CD010840_cognitive-behavioural-therapy-attention-deficit-hyperactivity-disorder-adhd-adults",type:"research",finding:"14 studi randomizzati con 700 adulti valutavano interventi cognitivo comportamentali strutturati. I benefici sui sintomi dipendevano dal confronto; certezza da molto bassa a moderata.",limitation:"I programmi clinici sono diversi dalle impostazioni o dai timer di ODA. Pochi dati a lungo termine; il corso non offre valutazioni, trattamenti o consigli sui farmaci."},{id:"F13",title:"Ruiz Pardo e Minda · 2022 · Replica preregistrata dell’effetto «brain drain»",url:"https://pubmed.ncbi.nlm.nih.gov/36007374/",type:"research",finding:"Una replica diretta preregistrata del secondo esperimento originale sulla posizione del telefono non ritrovava differenze tra posizioni nei compiti esaminati.",limitation:"L’abstract originale conferma la mancata replica, senza numero totale di partecipanti o valore p esatto. Non prova effetti esattamente nulli ovunque, né l’innocuità dei controlli attivi del telefono."},{id:"F14",title:"Hartanto e colleghi · 2024 · Sintesi sulla sola presenza dello smartphone",url:"https://assets.pubpub.org/mgkf17za/tmb_tmb0000123-41706626995650.pdf",type:"research",finding:"33 studi, 53 campioni, 166 effetti: nessun peggioramento complessivo affidabile dalla sola presenza, d = -0,02 [-0,06; 0,01]. Il sottogruppo sulla memoria di lavoro perdeva significatività dopo la correzione delle distorsioni.",limitation:"L’articolo riporta totali discordanti dei partecipanti, quindi non ne diamo uno definitivo. Restano differenze tra compiti e sintesi; non studia controlli attivi o avvisi."},{id:"F15",title:"Cal Newport · 2013, aggiornato nel 2023 · Pianificare per fasce orarie",url:"https://calnewport.com/deep-habits-the-importance-of-planning-every-minute-of-your-work-day/",type:"technique",finding:"Newport descrive una propria routine con fasce dedicate, lavoro in risposta alle richieste e spazio per riscrivere il piano.",limitation:"Il racconto pratico non presenta studi d’intervento o stime dell’effetto. Non stabilisce se esistano studi controllati su questa precisa routine."},{id:"F16",title:"Parry · 2024 · Metanalisi dell’effetto «brain drain»",url:"https://research.vu.nl/en/publications/does-the-mere-presence-of-a-smartphone-impact-cognitive-performan/",type:"research",finding:"Una sintesi alternativa rilevava un peggioramento medio della memoria di lavoro, mentre le sintesi delle altre funzioni cognitive davano risultati nulli.",limitation:"Disponibile solo l’abstract; effetti complessivi esatti e unità di conteggio degli studi non verificati. Eterogeneità e scarsa potenza statistica limitano le conclusioni. Presenza e uso attivo sono distinti."},{id:"task-switching",title:"Monsell · 2003 · Passare da un compito all’altro",url:"https://psychfiles.net/experimental/Monsell_2003.pdf",type:"research",finding:"Negli studi di laboratorio su compiti semplici, dopo un cambio le risposte erano più lente e spesso meno accurate. Prepararsi riduceva questo costo senza eliminarlo in modo affidabile.",limitation:"Rassegna narrativa, senza una stima complessiva delle perdite sul lavoro. Non indica tempi universali di ripresa, percentuali di produttività o verifiche dei suggerimenti di preparazione di ODA."},{id:"interruptions",title:"Mark, Gudith e Klocke · 2008 · Lavoro interrotto, velocità e stress",url:"https://ics.uci.edu/~gmark/chi08-mark.pdf",type:"research",finding:"48 partecipanti, in un lavoro simulato sulle email, impiegavano meno tempo netto con interruzioni ma riferivano più stress. Il tempo per gestire le interruzioni era sottratto.",limitation:"Campione piccolo, soprattutto studenti. Non dimostra meno tempo totale, qualità invariata garantita, effetti duraturi sullo stress o un tempo universale di ripresa."},{id:"notifications",title:"Kushlev, Proulx e Dunn · 2016 · Telefono con meno interruzioni",url:"https://interruptions.net/literature/Kushlev-CHI16.pdf",type:"research",finding:"221 studenti provarono due configurazioni per una settimana ciascuna. I confronti appaiati sui sintomi comprendevano 190 rispondenti. Avvisi disattivati e telefono fuori vista riducevano modestamente la disattenzione riferita: 2,27 contro 2,38; d = 0,44.",limitation:"Avvisi e visibilità/accessibilità cambiavano insieme. Autovalutazioni in uno studio non in cieco; non isola gli avvisi, non tratta l’ADHD e non mostra un miglioramento diretto significativo della produttività."},{id:"phone-presence",title:"Hartanto e colleghi · 2024 · Sintesi sulla sola presenza dello smartphone",url:"https://assets.pubpub.org/mgkf17za/tmb_tmb0000123-41706626995650.pdf",type:"research",finding:"33 studi, 53 campioni, 166 effetti: nessun peggioramento complessivo affidabile dalla sola presenza, d = -0,02 [-0,06; 0,01]. Il sottogruppo sulla memoria di lavoro perdeva significatività dopo la correzione delle distorsioni.",limitation:"L’articolo riporta totali discordanti dei partecipanti, quindi non ne diamo uno definitivo. Restano differenze tra compiti e sintesi; non studia controlli attivi o avvisi."},{id:"brain-drain-replication",title:"Ruiz Pardo e Minda · 2022 · Replica preregistrata dell’effetto «brain drain»",url:"https://pubmed.ncbi.nlm.nih.gov/36007374/",type:"research",finding:"Una replica diretta preregistrata del secondo esperimento originale sulla posizione del telefono non ritrovava differenze tra posizioni nei compiti esaminati.",limitation:"L’abstract originale conferma la mancata replica, senza numero totale di partecipanti o valore p esatto. Non prova effetti esattamente nulli ovunque, né l’innocuità dei controlli attivi del telefono."},{id:"microbreaks",title:"Albulescu e colleghi · 2022 · Brevi pause",url:"https://doi.org/10.1371/journal.pone.0272460",type:"research",finding:"22 campioni, 2.335 partecipanti: energia d = 0,36 [0,16; 0,55], miglioramento della fatica 0,35 [0,19; 0,50], prestazione 0,16 [-0,04; 0,37].",limitation:"Campioni diversi per ciascun esito; dati limitati ed eterogenei. Non stabilisce durata o attività ideali, benefici affidabili sui compiti impegnativi o che ogni svago davanti a uno schermo impedisca di recuperare energia."},{id:"focus-ready-to-resume",title:"Leroy e Glomb · 2018 · Interruzioni e piani per riprendere",url:"https://ideas.repec.org/a/inm/ororsc/v29y2018i3p380-397.html",type:"research",finding:"Quattro studi riportavano che pianificare la ripresa riduceva l’attenzione rimasta sul compito precedente e favoriva decisioni o il ricordo delle informazioni nel nuovo compito. Il primo studio sul campo era un’indagine.",limitation:"Disponibili solo abstract e sintesi universitaria. Scheda esatta, durata ed effetti complessivi non verificati. Nessun beneficio dimostrato sul compito originale una volta ripreso."},{id:"focus-newport-time-blocking",title:"Cal Newport · 2013, aggiornato nel 2023 · Pianificare per fasce orarie",url:"https://calnewport.com/deep-habits-the-importance-of-planning-every-minute-of-your-work-day/",type:"technique",finding:"Newport descrive una propria routine con fasce dedicate, lavoro in risposta alle richieste e spazio per riscrivere il piano.",limitation:"Il racconto pratico non presenta studi d’intervento o stime dell’effetto. Non stabilisce se esistano studi controllati su questa precisa routine."},{id:"brain-drain",title:"Ward e colleghi · 2017 · Esperimenti originali sulla presenza del telefono",url:"https://www.journals.uchicago.edu/doi/full/10.1086/691462",type:"research",finding:"Gli esperimenti originali su studenti trovavano piccole differenze in alcune misure della memoria di lavoro secondo la posizione del telefono. L’attenzione sostenuta non mostrava lo stesso risultato.",limitation:"Una replica diretta preregistrata non ha confermato il risultato. Le rassegne discordano sulla memoria di lavoro; una non rileva peggioramenti complessivi affidabili. Il primo risultato da solo non è un fatto assodato."},{id:"focus-attention-residue",title:"Leroy · 2009 · Attenzione rimasta sul compito precedente",url:"https://ideas.repec.org/a/eee/jobhdp/v109y2009i2p168-181.html",type:"research",finding:"Due esperimenti riportavano pensieri persistenti sul compito precedente, accompagnati da prestazioni peggiori nel compito successivo.",limitation:"Disponibile solo l’abstract; mancano metodi dettagliati, totali dei campioni ed effetti. Non quantifica un costo quotidiano dell’attenzione e non consiglia pressioni continue sui tempi."}],i=[{schemaVersion:2,revision:2,id:"focus-1",courseId:"focus",locale:"it",title:"Giornata piena? Proteggi un passo utile",goal:"Completa una parte utile dell’attività scelta; annota come riprendere.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Un’ora tra le schede aperte e la relazione è ancora lì? Ora dai spazio al lavoro che hai scelto.",reason:{id:"focus-1-reason",label:"Quale attività importante continui a lasciare per passare ad altro?",kind:"text",maxLength:160,optional:!0,suggestions:["La relazione resta incompleta","Perdo il filo della conversazione","Le schede rubano tempo allo studio","Non ho ancora notato un costo"]},why:{id:"focus-1-purpose",label:"Che cosa potresti fare questa settimana grazie a questo passo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Scegli un’attività utile e mantienila per tutto il corso. In laboratorio, passare tra compiti semplici rallentava la risposta successiva e spesso aumentava gli errori. Prepararsi riduceva il costo senza eliminarlo in modo affidabile. Non è una percentuale universale di produttività persa.","Nel prossimo breve periodo di lavoro, completa una parte utile prima di passare volontariamente ad altro. Per una richiesta ordinaria, annota dove sei e come riprendere. È un adattamento pratico, senza prove di ripresa più rapida. Saltalo se sicurezza o assistenza richiedono un intervento immediato."],example:{title:"Giulia lascia un appunto per riprendere",text:"Dopo la riunione del mattino, Giulia lavora dieci minuti alla stessa relazione sul bilancio. Corregge una riga delle spese di trasferta prima di aprire le email. Un collega ha bisogno di una cifra a breve. Scrive «Controllare la riga 40», risponde e torna a quella riga. La relazione resta incompleta; la correzione e la ripresa ci sono state."}},move:{invitation:"Mantieni l’attività. Nuovo piano? Adatta risultato e momento di inizio di questo esempio.",instructions:["Indica attività e risultato concreti prima di salvare questo esempio modificabile.","Prima di un’interruzione ordinaria, annota come riprendere se puoi fermarti un attimo senza rischi."],prompts:[],suggestions:{action:["Correggi una riga della relazione; annota come riprendere","Scrivi una frase della proposta; annota come riprendere","Risolvi un esercizio; annota il passo successivo"],minimum:["Correggi una riga della relazione","Scrivi una frase utile della proposta","Risolvi un esercizio"],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1},{label:"Tra due giorni",daysFromToday:2}],cue:["Dopo la riunione di questa mattina","Dopo pranzo, prima delle email rimandabili","Dopo la prima pausa disponibile"],place:["Alla mia scrivania di lavoro","Al tavolo in cucina, con il necessario","Dove ho pronto il necessario"],minutes:[10,2,5],fallback:["Annota come riprendere prima di rispondere","Correggi una riga dopo la richiesta","Scegli la prossima occasione fattibile"],observation:["Risultato e primo passo per riprendere","Quali interruzioni erano necessarie","Quale passaggio evitabile ho rimandato"]},suggested:{action:"Correggi una riga della relazione; annota come riprendere",minimum:"Correggi una riga della relazione",minutes:10,cueHint:"Dopo la riunione di questa mattina",placeHint:"Alla mia scrivania di lavoro",obstacleHint:"Una richiesta ordinaria interrompe il lavoro",fallbackHint:"Annota come riprendere prima di rispondere",observationHint:"Risultato e primo passo per riprendere"},accessibleAlternative:"Usa la dettatura o un promemoria accessibile; anche due minuti per una parte utile dell’attività vanno bene.",stopRule:"Salta l’appunto nelle emergenze o se serve assistenza immediata; mantieni accessibili i contatti necessari."},result:{question:"Hai fatto il minimo scelto?",observationPrompt:"Che cosa hai fatto o prodotto davvero?"},judgment:{primary:{id:"focus-1-decision",scenario:"Giulia controlla i costi della relazione. Un collega ha bisogno di una cifra a breve. Non è un’emergenza e c’è tempo per un appunto veloce.",question:"Quale risposta rispetta entrambi i compiti?",options:[{id:"focus-1-answer-now",text:"Rispondere subito al collega e poi affidarsi alla memoria per ritrovare il punto lasciato in sospeso nella relazione.",feedback:"Rispondi alla richiesta, ma rinunci a un aiuto semplice già disponibile. Un appunto breve può indicare il passo successivo prima che Giulia si occupi della richiesta legittima."},{id:"focus-1-marker-first",text:"Annotare «Controllare la riga 40», gestire la richiesta necessaria e poi riprendere la relazione dal punto indicato.",feedback:"Rispetti la richiesta e conservi un passo concreto da riprendere. L’appunto è un aiuto pratico da provare, senza dimostrare che ogni interruzione sia innocua o la ripresa più rapida."},{id:"focus-1-finish-report",text:"Dire al collega che riceverà la cifra a relazione completa, poi continuare senza interrompersi.",feedback:"Proteggere il lavoro conta, ma la richiesta ha una scadenza e un appunto breve è fattibile. Finire tutto prima ignorerebbe questa necessità. Annota come riprendere, poi rispondi."}],bestOptionId:"focus-1-marker-first"}},carry:{takeaway:"Proteggi il lavoro utile e annota come riprendere. Le interruzioni necessarie meritano comunque risposta.",followUp:{questionId:"focus-1-return",question:"L’appunto ti indicava il prossimo passo concreto?",observationPrompt:"Che cosa è successo nell’occasione prevista?",adjustmentPrompt:"Quale cambiamento è adatto alla prossima occasione?"}},goDeeper:{sections:[{heading:"Il costo di cambiare compito ha limiti precisi",paragraphs:["La rassegna di Monsell del 2003 descrive esperimenti con compiti cognitivi semplici. Subito dopo un cambio, le risposte erano più lente e di solito meno accurate. Prepararsi in anticipo riduceva questo costo senza eliminarlo in modo affidabile. Non fornisce una percentuale complessiva di perdite sul lavoro o tempi universali di ripresa. [F01] Usa questa distinzione per scegliere cosa rimandare, senza considerare dannosa ogni interruzione.","Il piccolo esperimento di Mark e colleghi del 2008 simulava un lavoro sulle email. Con interruzioni, i partecipanti impiegavano meno tempo netto ma riferivano più stress. Il tempo per gestire le interruzioni era sottratto: non significa meno tempo totale. Le misure della qualità erano limitate e non garantiscono qualità invariata nel lavoro reale. [F07] Questo breve lavoro con risultato e appunto è un adattamento di ODA. Attività, ruolo, salute e responsabilità di assistenza determinano cosa sia fattibile. Conta una riga utile o un compito svolto, non il timer acceso o il conteggio che fai mentre rimandi il lavoro."]},{heading:"Che cosa misuravano i piani per riprendere",paragraphs:["L’articolo di Leroy e Glomb del 2018 riportava quattro studi sulle interruzioni e sull’attenzione rimasta al compito precedente. Pianificare la ripresa riduceva questa persistenza e favoriva decisioni o il ricordo delle informazioni nel compito che aveva interrotto il primo. Il primo studio sul campo era un’indagine su professionisti, non un esperimento d’intervento. L’abstract e la descrizione universitaria disponibili non dimostrano benefici sul compito originale una volta ripreso. [F10]","L’abstract e la descrizione universitaria non forniscono la scheda completa pubblicata o la durata sperimentale. Un appunto breve sul punto raggiunto e sulla prossima azione è quindi un adattamento di ODA ispirato alla fonte. Non ritardare emergenze o assistenza immediata per completarlo. Nelle pause ordinarie usa parole, dettatura o il tuo promemoria accessibile abituale. Quando riprendi, verifica se indicava un’azione fattibile. Riprendere più facilmente è un’osservazione, non una prova controllata del meccanismo. Annota cosa hai prodotto e cosa resta da fare, anche se il tempo disponibile si è accorciato."]}],sourceIds:["F01","F07","F10"]}},{schemaVersion:2,revision:2,id:"focus-2",courseId:"focus",locale:"it",title:"La chat insiste? Scegli cosa può aspettare",goal:"Prova l’attività scelta con un’interruzione evitabile in meno, preservando i contatti necessari.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Tre notifiche mentre scrivi una frase? Scegli cosa può aspettare finché finisci.",reason:{id:"focus-2-reason",label:"Chi ha bisogno di te ora e che cosa può aspettare senza rischi?",kind:"text",maxLength:160,optional:!0,suggestions:["Assistenza ora; chat di gruppo dopo","Scadenza cliente ora; newsletter dopo","Nessun contatto necessario in questo momento","Le chiamate di lavoro necessarie non aspettano"]},why:{id:"focus-2-purpose",label:"Che cosa potresti fare questa settimana grazie a questo passo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Mantieni l’attività e verifica chi deve poterti raggiungere. Un esperimento sul telefono cambiava insieme avvisi e visibilità. Gli studenti riferivano meno sintomi legati all’attenzione nella settimana con meno interruzioni. Non isolava le notifiche e non dimostrava che la configurazione trattasse l’ADHD.","Tieni conto di questo limite nel tuo esperimento. Prima mantieni aperti i canali necessari. Poi modifica un’impostazione non essenziale per un breve lavoro fattibile, lasciando il telefono dov’era. Il lavoro è la parte utile che produci. Silenziare un’app è preparazione. Scegli quando controllare i messaggi rispettando responsabilità di assistenza e lavoro."],example:{title:"Giulia sceglie quando essere disponibile",text:"Giulia mantiene la relazione e i dieci minuti disponibili. Suo padre potrebbe chiamarla: verifica che possa raggiungerla. Silenzia soltanto la chat non urgente e lascia il telefono dov’era. Corregge un’altra riga del bilancio. Una richiesta di lavoro la interrompe comunque; la annota e lascia un appunto per riprendere."}},move:{invitation:"Mantieni il risultato. Nuovo piano? Adatta questo esempio e preserva i contatti necessari.",instructions:["Verifica i contatti necessari prima di cambiare un’impostazione per le interruzioni evitabili.","Indica il risultato e un’occasione reale; le sole impostazioni sono preparazione."],prompts:[],suggestions:{action:["Correggi una riga con la chat silenziata","Scrivi una frase con la chat silenziata","Risolvi un esercizio tra i controlli necessari"],minimum:["Correggi una riga; resta raggiungibile","Scrivi una frase; resta raggiungibile","Risolvi un esercizio tra i controlli necessari"],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1},{label:"Tra due giorni",daysFromToday:2}],cue:["Dopo il controllo dei messaggi necessario oggi","Dopo pranzo, prima delle email rimandabili","Dopo il controllo programmato dei messaggi"],place:["Alla mia scrivania di lavoro","Tavolo in cucina, telefono a portata di mano","Alla mia solita scrivania di lavoro"],minutes:[10,2,5],fallback:["Mantieni le chiamate; silenzia solo la chat","Ripristina i contatti e cambia un’altra impostazione","Scrivi una frase tra i controlli necessari"],observation:["Risultato e interruzioni necessarie","Se i contatti necessari potevano raggiungermi","Quale impostazione non essenziale ho cambiato"]},suggested:{action:"Correggi una riga con la chat silenziata",minimum:"Correggi una riga; resta raggiungibile",minutes:10,cueHint:"Dopo il controllo dei messaggi necessario oggi",placeHint:"Alla mia scrivania di lavoro",obstacleHint:"Non so se un contatto necessario può raggiungermi",fallbackHint:"Mantieni le chiamate; silenzia solo la chat",observationHint:"Risultato e interruzioni necessarie"},accessibleAlternative:"Usa una scheda visibile o un promemoria accessibile; mantieni calendari e strumenti di comunicazione necessari.",stopRule:"Mantieni accessibili emergenze, assistenza e lavoro necessario; non fidarti di eccezioni mai verificate."},result:{question:"Hai fatto il minimo scelto?",observationPrompt:"Che cosa hai fatto o prodotto davvero?"},judgment:{primary:{id:"focus-2-decision",scenario:"Giulia ha dieci minuti per la relazione, un genitore che potrebbe chiamarla e continue notifiche della chat non urgente. Le eccezioni per i contatti non sono verificate.",question:"Che cosa dovrebbe fare prima?",options:[{id:"focus-2-silence-all",text:"Attivare la modalità concentrazione predefinita per ridurre le notifiche, lasciando il telefono visibile se il genitore chiama.",feedback:"Riduce le interruzioni, ma vedere il telefono non verifica le eccezioni della modalità predefinita. Controlla che il canale necessario per l’assistenza resti accessibile prima di attivare impostazioni che potrebbero bloccarlo."},{id:"focus-2-rely-on-restraint",text:"Lasciare tutti gli avvisi attivi e decidere ogni volta se il messaggio merita una risposta immediata.",feedback:"Mantiene i contatti accessibili, ma lascia intatte le interruzioni evitabili. Giulia può silenziare la chat continuando a ricevere le chiamate necessarie per l’assistenza."},{id:"focus-2-preserve-access",text:"Verificare le chiamate necessarie, silenziare la chat non urgente, poi lavorare alla relazione e controllare i messaggi dopo.",feedback:"Protegge il lavoro e rispetta la reale necessità di assistenza. Le impostazioni sono preparazione. Annota il lavoro sulla relazione separatamente e correggi ogni eccezione che non ha funzionato come previsto."}],bestOptionId:"focus-2-preserve-access"}},carry:{takeaway:"Essere disponibili comporta scelte e responsabilità. Riduci le interruzioni evitabili mantenendo i contatti necessari.",followUp:{questionId:"focus-2-return",question:"L’impostazione proteggeva il lavoro e lasciava accessibili i contatti necessari?",observationPrompt:"Che cosa è successo nell’occasione prevista?",adjustmentPrompt:"Quale cambiamento è adatto alla prossima occasione?"}},goDeeper:{sections:[{heading:"L’esperimento cambiava più cose insieme",paragraphs:["L’esperimento controbilanciato di Kushlev e colleghi del 2016 coinvolgeva 221 universitari. Nella settimana con più interruzioni, gli avvisi erano attivi e il telefono visibile e raggiungibile. Nell’altra, avvisi sonori, vibrazione e avvisi visivi erano disattivati e il telefono fuori vista. Le modifiche avvenivano insieme. I confronti appaiati sui sintomi comprendevano 190 rispondenti. [F06]","La disattenzione media riferita era 2,38 contro 2,27 su una scala da uno a quattro, con d = 0,44 riportato. Anche l’iperattività riferita variava modestamente. I partecipanti conoscevano le impostazioni; era un unico breve esperimento su studenti. Non isolava gli avvisi, non dimostrava cause o trattamenti dell’ADHD, né un miglioramento diretto significativo della produttività. Qui cambi un’impostazione non essenziale mantenendo la posizione precedente. Questa prova più limitata è un adattamento di ODA, senza riprodurre il protocollo di una settimana. Annotare il risultato serve a vedere cosa è successo davvero nell’attività scelta."]},{heading:"Il limite deve rispettare il tuo ruolo",paragraphs:["Parti dalla reperibilità realmente necessaria. Una chiamata per assistenza, un canale di reperibilità o uno strumento di lavoro con tempi vincolanti possono richiedere risposta immediata. Non supporre che un’eccezione funzioni senza verificarla. Se non puoi confermarlo, lascia il canale accessibile e cambia un’altra interruzione evitabile. Questa è una regola di sicurezza e fattibilità del corso, non una promessa dello studio sul telefono. [F06]","Usa un promemoria esterno o un appunto visibile sul prossimo passo se rendono il lavoro accessibile. Controlla i messaggi dopo solo se il tuo ruolo lo consente. Un messaggio necessario bloccato richiede una correzione, anche se hai prodotto di più. Difficoltà persistenti dell’attenzione che incidono sulla vita quotidiana meritano una valutazione professionale; le impostazioni non sono cure. La rassegna Cochrane riguarda interventi cognitivo comportamentali strutturati per adulti con ADHD, non questa breve routine. [F11] Puoi chiedere aiuto ora, senza dover prima accumulare tentativi falliti col telefono. Rispetta attività, assistenza e fatti annotati."]}],sourceIds:["F06","F11"]}},{schemaVersion:2,revision:2,id:"focus-3",courseId:"focus",locale:"it",title:"Telefono a portata? Scegli quando prenderlo",goal:"Prova una posizione adatta per il telefono mentre lavori e annota separatamente impulsi e volte che lo prendi.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Il telefono sulla scrivania non dice quanto sei disciplinato. Guarda che cosa fai.",reason:{id:"focus-3-reason",label:"Che cosa succede appena prima di prendere il telefono?",kind:"text",maxLength:160,optional:!0,suggestions:["Una frase diventa difficile","Aspetto un messaggio necessario","Controllo senza accorgermene","Non ricordo un episodio recente"]},why:{id:"focus-3-purpose",label:"Che cosa potresti fare questa settimana grazie a questo passo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Telefono vicino e controlli continui sono due questioni diverse. Le rassegne discordano su alcuni compiti di memoria; una non rilevava peggioramenti complessivi affidabili dalla sola presenza. Nessuno dei due risultati chiarisce che cosa succede quando lo usi.","Mantieni simili attività, durata e avvisi nelle varie prove. Nessun tentativo annotato? Questo sarà il primo. Cambia posizione preservando i contatti necessari. In questa sessione e in quelle che confronti, annota gli impulsi e quante volte prendi il telefono. Carichi diversi e fatica limitano il confronto. Usa gli appunti per scegliere una sistemazione fattibile, senza attribuire al telefono la causa del risultato."],example:{title:"Giulia confronta le stesse osservazioni",text:"Giulia continua la relazione per dieci minuti, mantenendo gli avvisi necessari. Sposta il telefono dalla scrivania a una mensola accessibile. Annota quattro impulsi, una volta col telefono in mano e due righe corrette. Ieri aveva annotato cinque impulsi e tre volte col telefono in mano. Oggi c’erano meno richieste: la mensola merita un’altra prova, senza essere dimostrata migliore."}},move:{invitation:"Mantieni il risultato. Nuovo piano? Adatta questo esempio lasciando accessibile il telefono.",instructions:["Cambia solo posizione; mantieni confrontabili attività, durata, avvisi e contatti necessari.","Se contare distrae, annota dopo impulsi e quante volte lo prendi."],prompts:[],suggestions:{action:["Correggi una riga, telefono sulla mensola","Correggi una riga, telefono sulla scrivania","Scrivi una frase, telefono accessibile senza rischi"],minimum:["Correggi una riga della relazione","Scrivi una frase utile della relazione","Risolvi un esercizio"],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1},{label:"Tra due giorni",daysFromToday:2}],cue:["Dopo il controllo dei messaggi necessario oggi","Dopo aver verificato i contatti necessari","Dopo pranzo, prima delle email rimandabili"],place:["Alla scrivania, telefono sulla mensola raggiungibile","Alla scrivania, telefono accessibile senza rischi","Tavolo in cucina, telefono a portata di mano"],minutes:[10,2,5],fallback:["Smetti di contare; annota dopo, indicando i dubbi","Tieni il telefono accessibile dove ti distrae meno","Smetti di contare e proteggi il lavoro"],observation:["Impulsi, volte che prendo il telefono e risultato","Differenze tra i due periodi di lavoro","Se i contatti necessari restavano accessibili"]},suggested:{action:"Correggi una riga, telefono sulla mensola",minimum:"Correggi una riga della relazione",minutes:10,cueHint:"Dopo il controllo dei messaggi necessario oggi",placeHint:"Alla scrivania, telefono sulla mensola raggiungibile",obstacleHint:"Contare mi distrae dal lavoro",fallbackHint:"Smetti di contare durante il lavoro; annota dopo gli impulsi ricordati e quante volte l’hai preso. Indica le quantità incerte come incerte, non zero.",observationHint:"Impulsi, volte che prendo il telefono e risultato"},accessibleAlternative:"Usa un appunto a fine lavoro. Le quantità incerte restano incerte, non zero; i conteggi mancanti non cancellano il lavoro svolto.",stopRule:"Mantieni chiamate e calendario necessari accessibili; cambia posizione se rischi di bloccarli."},result:{question:"Hai fatto il minimo scelto?",observationPrompt:"Che cosa hai fatto o prodotto davvero?"},judgment:{primary:{id:"focus-3-decision",scenario:"Giulia ha preso il telefono meno spesso nel giorno più tranquillo col telefono sulla mensola. Domani le serve per lavorare. Altri dieci minuti sulla relazione consentono le stesse misure.",question:"Quale piano chiarisce dove tenere il telefono domani?",options:[{id:"focus-3-provisional-placement",text:"Ripetere attività e misure col telefono accessibile senza rischi, poi scegliere la posizione adatta al compito.",feedback:"Il lavoro di domani richiede il telefono: una nuova prova confrontabile rispetta questa esigenza. La giornata tranquilla col telefono sulla mensola suggerisce una preferenza, senza spiegare la causa della differenza."},{id:"focus-3-settled-placement",text:"Tenere il telefono sulla mensola per la settimana senza altri conteggi, usando la giornata tranquilla come preferenza pratica.",feedback:"Può essere una scelta fattibile se i contatti restano accessibili. Domani serve il telefono: lasciare tutto invariato ignora il nuovo vincolo. Prenderlo meno spesso non chiarisce neppure la causa."},{id:"focus-3-ignore-observations",text:"Tenere il telefono sulla scrivania perché una rassegna non rilevava svantaggi complessivi dalla sola presenza vicina.",feedback:"La scrivania può rispettare l’esigenza di domani. Ma una media sulla sola presenza non risponde alla domanda sui controlli di Giulia. Prova una sistemazione raggiungibile con misure confrontabili, senza scartare le osservazioni."}],bestOptionId:"focus-3-provisional-placement"}},carry:{takeaway:"Confronta gli stessi eventi. Usa le osservazioni per scegliere, senza trasformarle in un verdetto.",followUp:{questionId:"focus-3-return",question:"Attività, impostazioni, impulsi e volte che lo prendi erano abbastanza confrontabili per scegliere la prossima posizione?",observationPrompt:"Che cosa è successo nell’occasione prevista?",adjustmentPrompt:"Quale cambiamento è adatto alla prossima occasione?"}},goDeeper:{sections:[{heading:"Perché il titolo del giornale non basta",paragraphs:["La sintesi di Hartanto e colleghi del 2024 riuniva 33 studi, 53 campioni e 166 effetti. Non rilevava peggioramenti complessivi affidabili dalla sola presenza dello smartphone: d = -0,02, intervallo di confidenza al 95% da -0,06 a 0,01. Un sottogruppo sulla memoria di lavoro perdeva significatività dopo la correzione delle distorsioni. L’articolo riporta totali discordanti dei partecipanti: il corso non ne dà uno definitivo. [F14]","La sintesi alternativa di Parry del 2024 rilevava un peggioramento medio della memoria di lavoro, con risultati nulli nelle altre funzioni cognitive. L’abstract disponibile segnala differenze metodologiche e potenza statistica generalmente bassa; non fornisce l’effetto complessivo esatto. [F16] Queste rassegne richiedono cautela, senza dire «i telefoni non contano mai» o «un telefono vicino ti prosciuga sempre». Studiano entrambe la presenza, non i controlli attivi. La scrivania può essere adatta a un compito e una tentazione in un altro. Scegli secondo il ruolo e le osservazioni, senza giudicarti per la posizione."]},{heading:"Un confronto personale può comunque aiutarti",paragraphs:["La replica diretta preregistrata di Ruiz Pardo e Minda del 2022 non ritrovava l’effetto originale della posizione. L’abstract primario disponibile verifica il risultato senza numero totale di partecipanti o valore p esatto. Una mancata replica non dimostra effetti esattamente nulli per ciascuno e non studia scorrimento attivo o avvisi. [F13]","La tua breve prova affronta una domanda pratica: dove tenere il telefono mentre lavori e preservi i contatti necessari? Conta separatamente impulsi e volte che lo prendi, annotandoli entrambi in ogni sessione. Mantieni simili attività, durata e avvisi quando puoi. Segnala le richieste diverse, senza fingere condizioni da laboratorio. Un confronto fissato per domani è pianificato, non già tentato. Cambiare una sola variabile è una scelta progettuale di ODA, non un test diagnostico convalidato. Smetti di contare se sottrae tempo al lavoro utile. Puoi conservare una preferenza fattibile senza sapere con certezza perché abbia aiutato."]}],sourceIds:["F14","F16","F13"]}},{schemaVersion:2,revision:2,id:"focus-4",courseId:"focus",locale:"it",title:"Rileggi ancora? Fai una pausa con una ripresa chiara",goal:"Riposati come puoi, poi riprendi un passo utile nell’attività già scelta.",minutes:{learning:6,suggestedAction:3,review:2},direction:{hook:"Sempre sulla stessa riga? Il prossimo passo può essere una pausa.",reason:{id:"focus-4-reason",label:"Che costo ha rinunciare a una pausa per il resto della giornata?",kind:"text",maxLength:160,optional:!0,suggestions:["Rileggo invece di decidere","Dopo ho meno pazienza","Non ho ancora notato un costo","Ora una pausa non è fattibile"]},why:{id:"focus-4-purpose",label:"Che cosa potresti fare questa settimana grazie a questo passo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Una rassegna rilevava miglioramenti medi di energia e fatica con brevi pause, mentre l’effetto complessivo sulla prestazione era incerto. Il riposo conta anche senza farti andare più veloce. Non emergeva una durata o un’attività ideale per tutti.","Mantieni l’attività. Se è comparsa fatica, prova il riposo; altrimenti conserva il piano fattibile. Scegli una pausa possibile e indica il primo passo utile da riprendere. Va bene riposare seduto. Mantieni i contatti necessari per l’assistenza. Osserva fatica e ripresa; puoi sentirti come prima. Se serve più riposo o aiuto, cambia piano senza forzarti a riprendere."],example:{title:"Giulia si riposa e riprende",text:"Giulia corregge righe di bilancio da dieci minuti e continua a rileggere un appunto. Decide come riprendere: spiegare la variazione delle spese di trasferta. Riposa seduta due minuti, lasciando accessibili le chiamate per assistenza, poi scrive una frase esplicativa. È ancora stanca. Annota pausa e ripresa, senza sostenere di aver lavorato più velocemente."}},move:{invitation:"Mantieni il passo da riprendere. Serve riposo? Adatta questo esempio con pausa da seduto.",instructions:["Indica il risultato concreto da produrre alla ripresa prima di salvare l’esempio modificabile.","Riposa, poi prova quel passo se è adatto; annota entrambi con sincerità."],prompts:[],suggestions:{action:["Riposa seduto, poi spiega una modifica","Pausa da seduto, poi correggi una riga"],minimum:["Riposa e scrivi una spiegazione","Riposa e correggi una riga di bilancio"],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1},{label:"Tra due giorni",daysFromToday:2}],cue:["Dopo il lavoro sulla relazione","Quando rileggo senza avanzare","Alla breve pausa concordata"],place:["Seduto alla mia scrivania di lavoro","In un luogo vicino e accessibile per riposare","Dove resto raggiungibile per le chiamate necessarie"],minutes:[3,2,5],fallback:["Riposa quanto serve e riprogramma la ripresa","Prova una pausa più breve e accessibile","Chiedi copertura per il tempo di recupero"],observation:["Se ho riposato e ripreso il passo","Fatica prima e dopo la pausa","La riga utile scritta alla ripresa"]},suggested:{action:"Riposa seduto, poi spiega una modifica",minimum:"Riposa e scrivi una spiegazione",minutes:3,cueHint:"Dopo il lavoro sulla relazione",placeHint:"Seduto alla mia scrivania di lavoro",obstacleHint:"La ripresa prevista richiede energie che non ho",fallbackHint:"Riposa quanto serve e riprogramma la ripresa",observationHint:"Se ho riposato e ripreso il passo"},accessibleAlternative:"Riposa seduto o senza muoverti. Serve solo riposo? Scegli «Adatta questo passo», poi «Riposo».",stopRule:"Mantieni i contatti per l’assistenza; se riprendere non è adatto, scegli riposo, supporto o un’altra occasione."},result:{question:"Hai fatto il minimo scelto?",observationPrompt:"Che cosa hai fatto o prodotto davvero?"},judgment:{primary:{id:"focus-4-decision",scenario:"Giulia è esausta dopo la relazione e ha cinque minuti prima di una chiamata necessaria. Dopo riposo da seduta, una frase esplicativa resta fattibile.",question:"Quale pausa è adatta al tempo disponibile?",options:[{id:"focus-4-messages-break",text:"Usare i cinque minuti per recuperare messaggi di lavoro, poi riprendere ciò che sembra più urgente.",feedback:"I messaggi possono essere lavoro necessario, ma aggiungono richieste e non chiariscono la ripresa. Qui c’è tempo per riposo breve e una frase prima della chiamata."},{id:"focus-4-rest-return",text:"Riposare seduta due minuti, mantenere accessibili le chiamate necessarie, poi scrivere la frase scelta se le energie lo consentono.",feedback:"Prova il recupero mantenendo una ripresa utile e la chiamata necessaria. La fatica può restare invariata. Se mancano energie per la frase, annotalo e modifica il piano."},{id:"focus-4-finish-before-rest",text:"Finire la spiegazione prima della chiamata, così dopo può fare una pausa più lunga senza lasciare nulla in sospeso.",feedback:"Finire prima può funzionare quando le energie lo permettono. Qui Giulia è già esausta e una pausa breve è fattibile. Prova a riposare prima della frase possibile, senza rimandare automaticamente il recupero."}],bestOptionId:"focus-4-rest-return"}},carry:{takeaway:"Il riposo è cura di te. Sapere come riprendere chiarisce il tentativo successivo, senza garantire nuove energie.",followUp:{questionId:"focus-4-return",question:"La pausa rispondeva ai tuoi bisogni? Il passo scelto per riprendere era ancora fattibile?",observationPrompt:"Che cosa è successo nell’occasione prevista?",adjustmentPrompt:"Quale cambiamento è adatto alla prossima occasione?"}},goDeeper:{sections:[{heading:"Recuperare e produrre sono risultati diversi",paragraphs:["La rassegna di Albulescu e colleghi del 2022 riuniva 22 campioni e 2.335 partecipanti, studenti e lavoratori. Pause fino a dieci minuti miglioravano in media l’energia, d = 0,36 con intervallo di confidenza al 95% da 0,16 a 0,55, e la fatica, d = 0,35 da 0,19 a 0,50. La prestazione complessiva era incerta, d = 0,16 da -0,04 a 0,37. I campioni variavano secondo l’esito. [F02]","Questi dati limitati e vari non stabiliscono durata o attività ideali, né benefici affidabili sulla prestazione nei compiti cognitivi impegnativi. Due minuti seduti e una riga utile sono scelte accessibili del corso, non dosi ottimali dimostrate. Riposare lontano dallo schermo può essere adatto; la rassegna non dice che ogni svago sullo schermo impedisca di recuperare energia. Annota scelta e osservazioni. Il riposo può sostenere pazienza, recupero o presenza nella vita che vuoi, anche senza cambiare il risultato del lavoro. Non renderlo subordinato a finire ogni attività."]},{heading:"Prova gli intervalli, senza obbedire al timer",paragraphs:["Biwer e colleghi confrontavano pause fisse e scelte liberamente in una sessione di studio universitario di due ore. Le sequenze fisse erano 24 minuti di studio e sei di riposo, oppure 12 e tre. Dei 110 studenti randomizzati, 87 furono analizzati dopo dati mancanti ed esclusioni. Alcuni andamenti di fatica e concentrazione favorivano le pause fisse, senza differenza significativa nei compiti completati. Lo studio più lungo previsto fu ridotto a una sessione. [F08]","Non dimostra un intervallo universale o benefici duraturi sull’apprendimento. Scegli quando iniziare secondo il tuo ruolo e una pausa accessibile. Indica un’azione per riprendere, cambiandola se salute, assistenza o energie richiedono più recupero. Il timer è facoltativo; puoi partire da un evento concreto. Valutazioni della fatica e appunti precisi su risultato e ripresa sono adattamenti di ODA. Servono a scegliere la prossima prova, senza considerare un fallimento una sensazione invariata o una perdita di progressi una pausa più lunga necessaria."]}],sourceIds:["F02","F08"]}},{schemaVersion:2,revision:2,id:"focus-5",courseId:"focus",locale:"it",title:"Un martedì pieno? Fai un piano fattibile",goal:"Rivedi i tentativi, scegli gli aiuti della prossima settimana e prova un lavoro fattibile.",minutes:{learning:6,suggestedAction:10,review:2},direction:{hook:"Agenda piena e relazione ancora da finire? Conserva ciò che questa settimana ti ha fatto avanzare.",reason:{id:"focus-5-reason",label:"Che cosa rimanderai per proteggere un lavoro fattibile?",kind:"text",maxLength:160,optional:!0,suggestions:["Chat di gruppo non urgente","Ritocchi alla formattazione","Un seguito facoltativo alla riunione","Nulla è rimandabile; scegli un altro momento"]},why:{id:"focus-5-purpose",label:"Che cosa potresti fare questa settimana grazie a questo passo?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Rivedi cosa hai fatto davvero: risultati, interruzioni necessarie e un aiuto usato. Negli esperimenti, osservare più spesso i progressi migliorava in media il raggiungimento degli obiettivi. Non convalidava questa precisa routine. I tuoi appunti orientano una scelta, senza dimostrare le cause.","Mantieni gli aiuti fattibili. Cambia una condizione che gli appunti mettono in dubbio e scegli occasioni realistiche per la prossima settimana. Poi completa una parte utile secondo il piano. Senza tentativi precedenti, questa è la prima prova. Un impegno futuro resta pianificato. Timer e corso concluso non dimostrano che il lavoro sia avvenuto."],example:{title:"Giulia riscrive la settimana",text:"Giulia rilegge quattro tentativi sulla relazione. Silenziare la chat manteneva accessibili le chiamate per assistenza; dopo due pause ha ripreso. Al mattino arrivavano meno richieste di lavoro necessarie. Sceglie due brevi occasioni mattutine per la prossima settimana. Oggi una chiamata necessaria le lascia cinque minuti: scrive una spiegazione utile e annota il lavoro più breve. La relazione va ancora controllata."}},move:{invitation:"Mantieni azione e momento di inizio. Nuovo piano? Adatta l’esempio sulla relazione.",instructions:["Mantieni azione, minimo, momento e luogo; cambia un aiuto solo se serve.","Indica risultato e occasione concreti prima di salvare questo esempio modificabile.","Scegli le occasioni della prossima settimana rispettando impegni e recupero, poi prova il passo attuale."],prompts:[],suggestions:{action:["Scrivi una spiegazione con la chat silenziata","Correggi una riga restando raggiungibile","Scrivi una frase della proposta dopo una pausa"],minimum:["Scrivi una spiegazione utile nella relazione","Correggi una riga di bilancio","Scrivi una frase utile della proposta"],when:[{label:"Oggi",daysFromToday:0},{label:"Domani",daysFromToday:1},{label:"Tra due giorni",daysFromToday:2}],cue:["Dopo la riunione necessaria di questa mattina","Dopo la riunione necessaria","Dopo pranzo, prima delle email rimandabili"],place:["Alla mia scrivania di lavoro","Al tavolo in cucina, con il necessario","Dove i contatti necessari possono raggiungermi"],minutes:[10,2,5],fallback:["Scrivi una frase prima della chiamata","Annota come riprendere e gestisci la richiesta","Riposa quanto serve e scegli un altro momento"],observation:["Risultato concreto e una modifica al piano","Quale aiuto ho mantenuto o cambiato","Se il piano rispettava i miei impegni"]},suggested:{action:"Scrivi una spiegazione con la chat silenziata",minimum:"Scrivi una spiegazione utile nella relazione",minutes:10,cueHint:"Dopo la riunione necessaria di questa mattina",placeHint:"Alla mia scrivania di lavoro",obstacleHint:"Un impegno necessario accorcia il tempo di lavoro",fallbackHint:"Scrivi una frase prima della chiamata",observationHint:"Risultato concreto e una modifica al piano"},accessibleAlternative:"Usa strumenti accessibili, assistenza o un compito utile più breve; i promemoria esterni vanno bene.",stopRule:"Preserva contatti necessari e recupero; chiedi supporto per difficoltà persistenti senza aspettare la fine del corso."},result:{question:"Hai fatto il minimo scelto?",observationPrompt:"Che cosa hai fatto o prodotto davvero?"},judgment:{primary:{id:"focus-5-decision",scenario:"Giulia aveva previsto dieci minuti, ma una chiamata necessaria ne lascia cinque. Una frase esplicativa è fattibile e i contatti per assistenza restano accessibili.",question:"Quale modifica usa bene i suoi appunti?",options:[{id:"focus-5-wait-full-block",text:"Rimandare la relazione a dieci minuti interi domani e usare il tempo rimasto per pianificare.",feedback:"Pianificare può proteggere un’altra occasione, ma è preparazione. Ora una frase utile è fattibile. Provala, annota la durata reale più breve e lascia il piano futuro come pianificato."},{id:"focus-5-extend-evening",text:"Spostare tutti i dieci minuti nel tempo di recupero serale, già breve, così il programma originale risulta completo oggi.",feedback:"A volte un momento successivo può andare bene, ma qui si sacrifica recupero necessario per conservare la durata iniziale. Completa la parte più piccola fattibile e rivedi il lavoro rimasto."},{id:"focus-5-smaller-output",text:"Scrivere la frase fattibile, annotare il lavoro più breve e riprogrammare la prossima occasione secondo gli impegni reali.",feedback:"Conserva un risultato utile e rispetta chiamata e recupero. Annota i fatti senza dichiarare dieci minuti. Usa questi dati per pianificare un’altra occasione fattibile."}],bestOptionId:"focus-5-smaller-output"}},carry:{takeaway:"Mantieni risultato utile, contatti necessari e recupero. Lascia che i tuoi appunti guidino il prossimo piano.",followUp:{questionId:"focus-5-return",question:"Che cosa hai prodotto dopo la modifica?",observationPrompt:"Che cosa è successo nell’occasione prevista?",adjustmentPrompt:"Quale cambiamento è adatto alla prossima occasione?"}},goDeeper:{sections:[{heading:"Che cosa possono dirti i tuoi appunti",paragraphs:["La rassegna di Harkin e colleghi del 2016 riuniva 138 studi randomizzati con 19.951 partecipanti complessivi. Gli interventi che aumentavano l’osservazione dei progressi miglioravano in media il raggiungimento degli obiettivi, d = 0,40 con intervallo di confidenza al 95% da 0,32 a 0,48. Obiettivi e metodi variavano molto. Le associazioni con appunti scritti o comunicazioni pubbliche non dimostrano la superiorità di questi appunti privati sulla concentrazione. [F03]","Distingui negli appunti il tempo promesso, il tentativo reale, il risultato utile e la verifica successiva. Un timer misura solo il tempo trascorso. Una relazione incompleta può contenere righe realmente finite; un’agenda bella non dimostra che tu abbia scritto. Distingui interruzioni necessarie ed evitabili. Se la sistemazione apparentemente migliore coincideva con un giorno tranquillo, trattala come preferenza da riprovare. Scegli una modifica legata a un problema osservato, senza sostituire tutti gli aiuti insieme. Questa sequenza è una scelta progettuale di ODA, non un trattamento sperimentato o un’analisi delle cause."]},{heading:"Il piano deve adattarsi al lavoro e alla tua vita",paragraphs:["Cal Newport descrive la pianificazione per fasce orarie come metodo personale, con spazio per riscrivere la giornata e rispondere alle richieste. I suoi racconti di maggiore produzione sono impressioni pratiche, non risultati d’intervento misurati. Questo racconto non presenta prove sperimentali della routine. [F15] Non devi programmare ogni minuto lavorativo. Mantieni momento di inizio, contatti accessibili senza rischi, minimo utile e possibilità di recupero che hanno aiutato nella settimana.","Fissa una verifica e occasioni realistiche per la prossima settimana, poi prova il prossimo compito breve. Se difficoltà persistenti dell’attenzione compromettono la vita quotidiana, chiedi una valutazione professionale senza aspettare la fine del corso. È una raccomandazione di sicurezza, non un risultato degli studi sul monitoraggio. La rassegna Cochrane riguarda trattamenti strutturati dell’ADHD diagnosticato negli adulti; non dà soglie diagnostiche per l’app. [F11] Una pausa o una richiesta sincera di supporto può concludere l’apprendimento. Solo una parte concreta dell’attività riferita come svolta documenta che il lavoro è avvenuto."]}],sourceIds:["F03","F15","F11"]}}],n=[{id:"focus-1",photo:{id:"1745474633597-be94033b16d6",alt:"Una persona lavora al portatile e guarda il telefono"},schemaVersion:2,title:"Giornata piena? Proteggi un passo utile",minutes:6,goal:"Completa una parte utile dell’attività scelta; annota come riprendere.",reading:["Scegli un’attività utile e mantienila per tutto il corso. In laboratorio, passare tra compiti semplici rallentava la risposta successiva e spesso aumentava gli errori. Prepararsi riduceva il costo senza eliminarlo in modo affidabile. Non è una percentuale universale di produttività persa.","Nel prossimo breve periodo di lavoro, completa una parte utile prima di passare volontariamente ad altro. Per una richiesta ordinaria, annota dove sei e come riprendere. È un adattamento pratico, senza prove di ripresa più rapida. Saltalo se sicurezza o assistenza richiedono un intervento immediato."],practice:["Nella prossima ora, fai un segno ogni volta che passi a un’altra attività o app.","Distingui i passaggi: quanti li hai scelti tu e quanti venivano da notifiche o altre persone?","Prima del prossimo cambio, prova una frase breve per prepararti: «Ora passo a...»"],reflection:"Come hai vissuto questi passaggi?",question:"Secondo questa lezione, quale costo possono avere le interruzioni?",options:["Fanno sempre finire molto più lentamente.","Non hanno alcun costo.","Anche senza perdere velocità, puoi sentire più stress e pressione."],correct:2,feedback:"In un piccolo lavoro simulato sulle email, le interruzioni riducevano il tempo netto ma aumentavano lo stress riferito. Il tempo per gestirle era sottratto; non era meno tempo totale.",takeaway:"Proteggi il lavoro utile e annota come riprendere. Le interruzioni necessarie meritano comunque risposta.",sources:["F01","F07","F10"],deeper:[{heading:"Il costo di cambiare compito ha limiti precisi",paragraphs:["La rassegna di Monsell del 2003 descrive esperimenti con compiti cognitivi semplici. Subito dopo un cambio, le risposte erano più lente e di solito meno accurate. Prepararsi in anticipo riduceva questo costo senza eliminarlo in modo affidabile. Non fornisce una percentuale complessiva di perdite sul lavoro o tempi universali di ripresa. [F01] Usa questa distinzione per scegliere cosa rimandare, senza considerare dannosa ogni interruzione.","Il piccolo esperimento di Mark e colleghi del 2008 simulava un lavoro sulle email. Con interruzioni, i partecipanti impiegavano meno tempo netto ma riferivano più stress. Il tempo per gestire le interruzioni era sottratto: non significa meno tempo totale. Le misure della qualità erano limitate e non garantiscono qualità invariata nel lavoro reale. [F07] Questo breve lavoro con risultato e appunto è un adattamento di ODA. Attività, ruolo, salute e responsabilità di assistenza determinano cosa sia fattibile. Conta una riga utile o un compito svolto, non il timer acceso o il conteggio che fai mentre rimandi il lavoro."]},{heading:"Che cosa misuravano i piani per riprendere",paragraphs:["L’articolo di Leroy e Glomb del 2018 riportava quattro studi sulle interruzioni e sull’attenzione rimasta al compito precedente. Pianificare la ripresa riduceva questa persistenza e favoriva decisioni o il ricordo delle informazioni nel compito che aveva interrotto il primo. Il primo studio sul campo era un’indagine su professionisti, non un esperimento d’intervento. L’abstract e la descrizione universitaria disponibili non dimostrano benefici sul compito originale una volta ripreso. [F10]","L’abstract e la descrizione universitaria non forniscono la scheda completa pubblicata o la durata sperimentale. Un appunto breve sul punto raggiunto e sulla prossima azione è quindi un adattamento di ODA ispirato alla fonte. Non ritardare emergenze o assistenza immediata per completarlo. Nelle pause ordinarie usa parole, dettatura o il tuo promemoria accessibile abituale. Quando riprendi, verifica se indicava un’azione fattibile. Riprendere più facilmente è un’osservazione, non una prova controllata del meccanismo. Annota cosa hai prodotto e cosa resta da fare, anche se il tempo disponibile si è accorciato."]}],example:{title:"Giulia lascia un appunto per riprendere",text:"Dopo la riunione del mattino, Giulia lavora dieci minuti alla stessa relazione sul bilancio. Corregge una riga delle spese di trasferta prima di aprire le email. Un collega ha bisogno di una cifra a breve. Scrive «Controllare la riga 40», risponde e torna a quella riga. La relazione resta incompleta; la correzione e la ripresa ci sono state."}},{id:"focus-2",photo:{id:"1526045612212-70caf35c14df",alt:"Una persona tiene uno smartphone"},schemaVersion:2,title:"La chat insiste? Scegli cosa può aspettare",minutes:6,goal:"Prova l’attività scelta con un’interruzione evitabile in meno, preservando i contatti necessari.",reading:["Mantieni l’attività e verifica chi deve poterti raggiungere. Un esperimento sul telefono cambiava insieme avvisi e visibilità. Gli studenti riferivano meno sintomi legati all’attenzione nella settimana con meno interruzioni. Non isolava le notifiche e non dimostrava che la configurazione trattasse l’ADHD.","Tieni conto di questo limite nel tuo esperimento. Prima mantieni aperti i canali necessari. Poi modifica un’impostazione non essenziale per un breve lavoro fattibile, lasciando il telefono dov’era. Il lavoro è la parte utile che produci. Silenziare un’app è preparazione. Scegli quando controllare i messaggi rispettando responsabilità di assistenza e lavoro."],practice:["Guarda quali app ti hanno inviato notifiche nell’ultima ora.","Disattiva o silenzia le notifiche di almeno due app che possono aspettare senza rischi.","Attiva «Non disturbare» per un periodo di lavoro e aggiungi eccezioni per chi potrebbe aver bisogno urgente di te."],reflection:"Quale notifica era facile silenziare e quale difficile?",question:"Quale sintesi descrive più fedelmente il risultato dello studio?",options:["La configurazione con meno interruzioni dava una modesta differenza nei sintomi riferiti dai partecipanti.","Le notifiche causano l’ADHD.","Disattivare le notifiche risolve tutti i problemi di attenzione."],correct:0,feedback:"Lo studio cambiava insieme avvisi e visibilità. I sintomi riferiti variavano modestamente; non isolava gli avvisi né dimostrava cure o miglioramenti diretti della produttività.",takeaway:"Essere disponibili comporta scelte e responsabilità. Riduci le interruzioni evitabili mantenendo i contatti necessari.",sources:["F06","F11"],deeper:[{heading:"L’esperimento cambiava più cose insieme",paragraphs:["L’esperimento controbilanciato di Kushlev e colleghi del 2016 coinvolgeva 221 universitari. Nella settimana con più interruzioni, gli avvisi erano attivi e il telefono visibile e raggiungibile. Nell’altra, avvisi sonori, vibrazione e avvisi visivi erano disattivati e il telefono fuori vista. Le modifiche avvenivano insieme. I confronti appaiati sui sintomi comprendevano 190 rispondenti. [F06]","La disattenzione media riferita era 2,38 contro 2,27 su una scala da uno a quattro, con d = 0,44 riportato. Anche l’iperattività riferita variava modestamente. I partecipanti conoscevano le impostazioni; era un unico breve esperimento su studenti. Non isolava gli avvisi, non dimostrava cause o trattamenti dell’ADHD, né un miglioramento diretto significativo della produttività. Qui cambi un’impostazione non essenziale mantenendo la posizione precedente. Questa prova più limitata è un adattamento di ODA, senza riprodurre il protocollo di una settimana. Annotare il risultato serve a vedere cosa è successo davvero nell’attività scelta."]},{heading:"Il limite deve rispettare il tuo ruolo",paragraphs:["Parti dalla reperibilità realmente necessaria. Una chiamata per assistenza, un canale di reperibilità o uno strumento di lavoro con tempi vincolanti possono richiedere risposta immediata. Non supporre che un’eccezione funzioni senza verificarla. Se non puoi confermarlo, lascia il canale accessibile e cambia un’altra interruzione evitabile. Questa è una regola di sicurezza e fattibilità del corso, non una promessa dello studio sul telefono. [F06]","Usa un promemoria esterno o un appunto visibile sul prossimo passo se rendono il lavoro accessibile. Controlla i messaggi dopo solo se il tuo ruolo lo consente. Un messaggio necessario bloccato richiede una correzione, anche se hai prodotto di più. Difficoltà persistenti dell’attenzione che incidono sulla vita quotidiana meritano una valutazione professionale; le impostazioni non sono cure. La rassegna Cochrane riguarda interventi cognitivo comportamentali strutturati per adulti con ADHD, non questa breve routine. [F11] Puoi chiedere aiuto ora, senza dover prima accumulare tentativi falliti col telefono. Rispetta attività, assistenza e fatti annotati."]}],example:{title:"Giulia sceglie quando essere disponibile",text:"Giulia mantiene la relazione e i dieci minuti disponibili. Suo padre potrebbe chiamarla: verifica che possa raggiungerla. Silenzia soltanto la chat non urgente e lascia il telefono dov’era. Corregge un’altra riga del bilancio. Una richiesta di lavoro la interrompe comunque; la annota e lascia un appunto per riprendere."}},{id:"focus-3",photo:{id:"1635398235411-2c41ca32ffbc",alt:"Un telefono su un tavolo di legno"},schemaVersion:2,title:"Telefono a portata? Scegli quando prenderlo",minutes:6,goal:"Prova una posizione adatta per il telefono mentre lavori e annota separatamente impulsi e volte che lo prendi.",reading:["Telefono vicino e controlli continui sono due questioni diverse. Le rassegne discordano su alcuni compiti di memoria; una non rilevava peggioramenti complessivi affidabili dalla sola presenza. Nessuno dei due risultati chiarisce che cosa succede quando lo usi.","Mantieni simili attività, durata e avvisi nelle varie prove. Nessun tentativo annotato? Questo sarà il primo. Cambia posizione preservando i contatti necessari. In questa sessione e in quelle che confronti, annota gli impulsi e quante volte prendi il telefono. Carichi diversi e fatica limitano il confronto. Usa gli appunti per scegliere una sistemazione fattibile, senza attribuire al telefono la causa del risultato."],practice:["Nota dove tieni di solito il telefono mentre lavori e quante volte lo prendi.","Per un periodo di lavoro, metti il telefono fuori portata e annota ogni impulso a prenderlo.","Un altro giorno, prova a tenerlo sulla scrivania silenziato; confronta i giorni attraverso le tue osservazioni."],reflection:"Che cosa ti pesa davvero: averlo lì o la voglia di prenderlo?",question:"Che cosa dicono i dati su un telefono semplicemente appoggiato sulla scrivania?",options:["Riduce sicuramente le capacità mentali.","Una rassegna non rileva peggioramenti complessivi affidabili; le sintesi sulla memoria discordano, e l’uso attivo è distinto.","Metterlo in un’altra stanza è inutile."],correct:1,feedback:"Le sintesi sulla memoria danno risultati discordanti per la sola presenza. Una non rileva peggioramenti complessivi affidabili. Questo non chiarisce i controlli attivi o le preferenze personali.",takeaway:"Confronta gli stessi eventi. Usa le osservazioni per scegliere, senza trasformarle in un verdetto.",sources:["F14","F16","F13"],deeper:[{heading:"Perché il titolo del giornale non basta",paragraphs:["La sintesi di Hartanto e colleghi del 2024 riuniva 33 studi, 53 campioni e 166 effetti. Non rilevava peggioramenti complessivi affidabili dalla sola presenza dello smartphone: d = -0,02, intervallo di confidenza al 95% da -0,06 a 0,01. Un sottogruppo sulla memoria di lavoro perdeva significatività dopo la correzione delle distorsioni. L’articolo riporta totali discordanti dei partecipanti: il corso non ne dà uno definitivo. [F14]","La sintesi alternativa di Parry del 2024 rilevava un peggioramento medio della memoria di lavoro, con risultati nulli nelle altre funzioni cognitive. L’abstract disponibile segnala differenze metodologiche e potenza statistica generalmente bassa; non fornisce l’effetto complessivo esatto. [F16] Queste rassegne richiedono cautela, senza dire «i telefoni non contano mai» o «un telefono vicino ti prosciuga sempre». Studiano entrambe la presenza, non i controlli attivi. La scrivania può essere adatta a un compito e una tentazione in un altro. Scegli secondo il ruolo e le osservazioni, senza giudicarti per la posizione."]},{heading:"Un confronto personale può comunque aiutarti",paragraphs:["La replica diretta preregistrata di Ruiz Pardo e Minda del 2022 non ritrovava l’effetto originale della posizione. L’abstract primario disponibile verifica il risultato senza numero totale di partecipanti o valore p esatto. Una mancata replica non dimostra effetti esattamente nulli per ciascuno e non studia scorrimento attivo o avvisi. [F13]","La tua breve prova affronta una domanda pratica: dove tenere il telefono mentre lavori e preservi i contatti necessari? Conta separatamente impulsi e volte che lo prendi, annotandoli entrambi in ogni sessione. Mantieni simili attività, durata e avvisi quando puoi. Segnala le richieste diverse, senza fingere condizioni da laboratorio. Un confronto fissato per domani è pianificato, non già tentato. Cambiare una sola variabile è una scelta progettuale di ODA, non un test diagnostico convalidato. Smetti di contare se sottrae tempo al lavoro utile. Puoi conservare una preferenza fattibile senza sapere con certezza perché abbia aiutato."]}],example:{title:"Giulia confronta le stesse osservazioni",text:"Giulia continua la relazione per dieci minuti, mantenendo gli avvisi necessari. Sposta il telefono dalla scrivania a una mensola accessibile. Annota quattro impulsi, una volta col telefono in mano e due righe corrette. Ieri aveva annotato cinque impulsi e tre volte col telefono in mano. Oggi c’erano meno richieste: la mensola merita un’altra prova, senza essere dimostrata migliore."}},{id:"focus-4",photo:{id:"1556833232-52da3e4bd5d8",alt:"Una donna cammina lungo un sentiero"},schemaVersion:2,title:"Rileggi ancora? Fai una pausa con una ripresa chiara",minutes:6,goal:"Riposati come puoi, poi riprendi un passo utile nell’attività già scelta.",reading:["Una rassegna rilevava miglioramenti medi di energia e fatica con brevi pause, mentre l’effetto complessivo sulla prestazione era incerto. Il riposo conta anche senza farti andare più veloce. Non emergeva una durata o un’attività ideale per tutti.","Mantieni l’attività. Se è comparsa fatica, prova il riposo; altrimenti conserva il piano fattibile. Scegli una pausa possibile e indica il primo passo utile da riprendere. Va bene riposare seduto. Mantieni i contatti necessari per l’assistenza. Osserva fatica e ripresa; puoi sentirti come prima. Se serve più riposo o aiuto, cambia piano senza forzarti a riprendere."],practice:["Prevedi una pausa da cinque a dieci minuti alla fine di un periodo di lavoro.","Per la pausa, scegli di allontanarti dallo schermo: prendere un bicchiere d’acqua, guardare fuori dalla finestra o fare due passi.","Prima e dopo la pausa, valuta la fatica da 1 a 5 e annotala."],reflection:"Che cosa è cambiato con la pausa e che cosa no?",question:"Quale affermazione sulle brevi pause rispetta meglio i dati?",options:["Migliorano sicuramente la prestazione in qualsiasi lavoro.","Fare una pausa è solo tempo perso.","Promettenti per energia e fatica; l’effetto sulla prestazione è incerto."],correct:2,feedback:"I dati sono più coerenti sul sentirsi meglio che sulla prestazione. Considera la pausa parte della cura di te, senza usarla soltanto per accelerare il lavoro.",takeaway:"Il riposo è cura di te. Sapere come riprendere chiarisce il tentativo successivo, senza garantire nuove energie.",sources:["F02","F08"],deeper:[{heading:"Recuperare e produrre sono risultati diversi",paragraphs:["La rassegna di Albulescu e colleghi del 2022 riuniva 22 campioni e 2.335 partecipanti, studenti e lavoratori. Pause fino a dieci minuti miglioravano in media l’energia, d = 0,36 con intervallo di confidenza al 95% da 0,16 a 0,55, e la fatica, d = 0,35 da 0,19 a 0,50. La prestazione complessiva era incerta, d = 0,16 da -0,04 a 0,37. I campioni variavano secondo l’esito. [F02]","Questi dati limitati e vari non stabiliscono durata o attività ideali, né benefici affidabili sulla prestazione nei compiti cognitivi impegnativi. Due minuti seduti e una riga utile sono scelte accessibili del corso, non dosi ottimali dimostrate. Riposare lontano dallo schermo può essere adatto; la rassegna non dice che ogni svago sullo schermo impedisca di recuperare energia. Annota scelta e osservazioni. Il riposo può sostenere pazienza, recupero o presenza nella vita che vuoi, anche senza cambiare il risultato del lavoro. Non renderlo subordinato a finire ogni attività."]},{heading:"Prova gli intervalli, senza obbedire al timer",paragraphs:["Biwer e colleghi confrontavano pause fisse e scelte liberamente in una sessione di studio universitario di due ore. Le sequenze fisse erano 24 minuti di studio e sei di riposo, oppure 12 e tre. Dei 110 studenti randomizzati, 87 furono analizzati dopo dati mancanti ed esclusioni. Alcuni andamenti di fatica e concentrazione favorivano le pause fisse, senza differenza significativa nei compiti completati. Lo studio più lungo previsto fu ridotto a una sessione. [F08]","Non dimostra un intervallo universale o benefici duraturi sull’apprendimento. Scegli quando iniziare secondo il tuo ruolo e una pausa accessibile. Indica un’azione per riprendere, cambiandola se salute, assistenza o energie richiedono più recupero. Il timer è facoltativo; puoi partire da un evento concreto. Valutazioni della fatica e appunti precisi su risultato e ripresa sono adattamenti di ODA. Servono a scegliere la prossima prova, senza considerare un fallimento una sensazione invariata o una perdita di progressi una pausa più lunga necessaria."]}],example:{title:"Giulia si riposa e riprende",text:"Giulia corregge righe di bilancio da dieci minuti e continua a rileggere un appunto. Decide come riprendere: spiegare la variazione delle spese di trasferta. Riposa seduta due minuti, lasciando accessibili le chiamate per assistenza, poi scrive una frase esplicativa. È ancora stanca. Annota pausa e ripresa, senza sostenere di aver lavorato più velocemente."}},{id:"focus-5",photo:{id:"1632772998001-cc9bf6f7c852",alt:"Un’agenda con due penne appoggiate sopra"},schemaVersion:2,title:"Un martedì pieno? Fai un piano fattibile",minutes:6,goal:"Rivedi i tentativi, scegli gli aiuti della prossima settimana e prova un lavoro fattibile.",reading:["Rivedi cosa hai fatto davvero: risultati, interruzioni necessarie e un aiuto usato. Negli esperimenti, osservare più spesso i progressi migliorava in media il raggiungimento degli obiettivi. Non convalidava questa precisa routine. I tuoi appunti orientano una scelta, senza dimostrare le cause.","Mantieni gli aiuti fattibili. Cambia una condizione che gli appunti mettono in dubbio e scegli occasioni realistiche per la prossima settimana. Poi completa una parte utile secondo il piano. Senza tentativi precedenti, questa è la prima prova. Un impegno futuro resta pianificato. Timer e corso concluso non dimostrano che il lavoro sia avvenuto."],practice:["Scegli un’attività per domani e un tempo adatto; va bene iniziare in piccolo.","Completa «Se mi distraggo, allora...» e configura le notifiche prima di iniziare.","Dopo lavoro e pausa, annota brevemente cosa ha funzionato e cosa cambieresti."],reflection:"Quale parte del piano ti aiuta di più?",question:"Qual è il modo più onesto di pianificare per fasce orarie?",options:["È il metodo migliore per tutti, dimostrato dai dati.","Un esperimento personale ragionevole: osservi il risultato e lo adatti.","Se salta un periodo di lavoro, la giornata è persa."],correct:1,feedback:"Pianificare per fasce orarie è un’opzione da provare. Il racconto dell’autore non presenta studi d’intervento sulla precisa routine. Pianificare il futuro non è tentare il lavoro; difficoltà persistenti meritano supporto professionale.",takeaway:"Mantieni risultato utile, contatti necessari e recupero. Lascia che i tuoi appunti guidino il prossimo piano.",sources:["F03","F15","F11"],deeper:[{heading:"Che cosa possono dirti i tuoi appunti",paragraphs:["La rassegna di Harkin e colleghi del 2016 riuniva 138 studi randomizzati con 19.951 partecipanti complessivi. Gli interventi che aumentavano l’osservazione dei progressi miglioravano in media il raggiungimento degli obiettivi, d = 0,40 con intervallo di confidenza al 95% da 0,32 a 0,48. Obiettivi e metodi variavano molto. Le associazioni con appunti scritti o comunicazioni pubbliche non dimostrano la superiorità di questi appunti privati sulla concentrazione. [F03]","Distingui negli appunti il tempo promesso, il tentativo reale, il risultato utile e la verifica successiva. Un timer misura solo il tempo trascorso. Una relazione incompleta può contenere righe realmente finite; un’agenda bella non dimostra che tu abbia scritto. Distingui interruzioni necessarie ed evitabili. Se la sistemazione apparentemente migliore coincideva con un giorno tranquillo, trattala come preferenza da riprovare. Scegli una modifica legata a un problema osservato, senza sostituire tutti gli aiuti insieme. Questa sequenza è una scelta progettuale di ODA, non un trattamento sperimentato o un’analisi delle cause."]},{heading:"Il piano deve adattarsi al lavoro e alla tua vita",paragraphs:["Cal Newport descrive la pianificazione per fasce orarie come metodo personale, con spazio per riscrivere la giornata e rispondere alle richieste. I suoi racconti di maggiore produzione sono impressioni pratiche, non risultati d’intervento misurati. Questo racconto non presenta prove sperimentali della routine. [F15] Non devi programmare ogni minuto lavorativo. Mantieni momento di inizio, contatti accessibili senza rischi, minimo utile e possibilità di recupero che hanno aiutato nella settimana.","Fissa una verifica e occasioni realistiche per la prossima settimana, poi prova il prossimo compito breve. Se difficoltà persistenti dell’attenzione compromettono la vita quotidiana, chiedi una valutazione professionale senza aspettare la fine del corso. È una raccomandazione di sicurezza, non un risultato degli studi sul monitoraggio. La rassegna Cochrane riguarda trattamenti strutturati dell’ADHD diagnosticato negli adulti; non dà soglie diagnostiche per l’app. [F11] Una pausa o una richiesta sincera di supporto può concludere l’apprendimento. Solo una parte concreta dell’attività riferita come svolta documenta che il lavoro è avvenuto."]}],example:{title:"Giulia riscrive la settimana",text:"Giulia rilegge quattro tentativi sulla relazione. Silenziare la chat manteneva accessibili le chiamate per assistenza; dopo due pause ha ripreso. Al mattino arrivavano meno richieste di lavoro necessarie. Sceglie due brevi occasioni mattutine per la prossima settimana. Oggi una chiamata necessaria le lascia cinque minuti: scrive una spiegazione utile e annota il lavoro più breve. La relazione va ancora controllata."}}],t={id:"focus",title:"Sempre di corsa? Scegli cosa conta",subtitle:"Cinque lezioni. Proteggi un’attività utile, resta raggiungibile quando serve e prova aiuti e pause compatibili con i tuoi impegni.",description:"Scegli un’attività importante per te. Prova impostazioni, posizione del telefono, appunti per riprendere e riposo, tenendo conto della tua vita.",scope:"Suggerimenti per il lavoro quotidiano, senza diagnosi o trattamenti dei disturbi dell’attenzione. Se le difficoltà persistono e incidono sulla vita quotidiana, parlane con un professionista sanitario. Non bloccare chiamate necessarie per emergenze, assistenza o lavoro.",outcome:"Un esperimento fattibile su un’attività, con risultati annotati, contatti necessari accessibili e un piano di lavoro e riposo per la settimana successiva.",photo:{id:"1505330622279-bf7d7fc918f4",alt:"Una scrivania luminosa e ordinata"},lang:"it",lessons:n.map((e,a)=>({...e,v2:i[a]}))},r=Object.freeze(Object.defineProperty({__proto__:null,COURSE:t,FOCUS_LESSONS_V2:i,SOURCES:o},Symbol.toStringTag,{value:"Module"}));export{r as f};
